// 1. Spatial Locality (Row-Major Access)
void optimal_access(int matrix[R][C]) {
    for (int i = 0; i < R; i++) {
        for (int j = 0; j < C; j++) {
            matrix[i][j] *= 2; // Sequential memory access
        }
    }
}

// 2. Poor Spatial Locality (Column-Major Access)
void suboptimal_access(int matrix[R][C]) {
    for (int j = 0; j < C; j++) {
        for (int i = 0; i < R; i++) {
            matrix[i][j] *= 2; // Large strides, cache misses
        }
    }
}

// 3. Temporal Locality (Loop Interchange/Tiling Concept)
// Reuse of B[k][j] and A[i][k] before eviction
void tiled_matmul(int A[N][N], int B[N][N], int C[N][N]) {
    const int TILE = 32;
    for (int ii = 0; ii < N; ii += TILE)
    for (int jj = 0; jj < N; jj += TILE)
    for (int kk = 0; kk < N; kk += TILE)
    for (int i = ii; i < ii + TILE; i++)
    for (int j = jj; j < jj + TILE; j++)
    for (int k = kk; k < kk + TILE; k++) {
        C[i][j] += A[i][k] * B[k][j];
    }
}

// 4. Struct vs. Array of Structs (Cache Line Padding/Alignment)
// Data often accessed together should be kept close
struct aligned_data {
    int x;
    int y;
    char status; // Padding ensures alignment efficiency
    // Cache line effects minimized
};

// 5. Cache Conflict Avoidance (Power-of-Two Strides)
// If array size N is a power of 2, array indices N and 2N
// may map to the same cache set (direct mapped/set-associative)
const int NON_POWER_OF_2 = 1001;
int array[NON_POWER_OF_2];
void access_pattern() {
    // Avoids repeated set conflicts common with N=1024
    for (int i = 0; i < NON_POWER_OF_2; i += 64) {
        array[i]++;
    }
}
